def _ev(model, expr):
    try:
        return model.eval(expr, model_completion=True)
    except Z3Exception:
        return None


def _show(v, local=None):
    """Deterministic, readable rendering of a value (of a local sort)."""
    import datetime
    if v is None:
        return "<unavailable>"
    kind = display_kind.get(local)
    if kind and is_int_value(v):
        n = v.as_long()
        epoch = datetime.datetime(1970, 1, 1)
        if kind == "date":
            return (epoch + datetime.timedelta(days=n)).date().isoformat()
        if kind == "timestamp":
            return (epoch + datetime.timedelta(seconds=n)).isoformat(" ")
        return "%02d:%02d:%02d" % (n // 3600, n % 3600 // 60, n % 60)
    if is_string_value(v):
        return repr(v.as_string())
    if is_fp_value(v):
        r = simplify(fpToReal(v))
        if is_rational_value(r) and not (v.isInf() or v.isNaN()):
            return repr(r.numerator_as_long() / r.denominator_as_long())
        return str(v)
    if is_rational_value(v) and v.denominator_as_long() != 1:
        return "%s (= %s)" % (v.as_decimal(12).rstrip("?"), v)
    return str(v)


def _key(v):
    """Deterministic sort key for values."""
    if is_int_value(v):
        return (0, v.as_long(), "")
    if is_rational_value(v):
        return (0, v.numerator_as_long() / v.denominator_as_long(), "")
    if is_string_value(v):
        return (2, 0, v.as_string())
    if is_fp_value(v):
        r = simplify(fpToReal(v))
        if is_rational_value(r):
            return (0, r.numerator_as_long() / r.denominator_as_long(), "")
    return (1, 0, str(v))


def _is_value(e):
    return (is_int_value(e) or is_rational_value(e) or is_string_value(e)
            or is_fp_value(e) or is_true(e) or is_false(e)
            or (is_const(e) and e.sort().kind() == Z3_UNINTERPRETED_SORT))


def _entries(model, decl):
    """Explicit (args, value) entries of decl's interpretation, and its
    default ('else') value; ([], None) when decl is uninterpreted."""
    if not any(d.eq(decl) for d in model.decls()):
        return [], None                       # no interpretation: all false
    try:
        fi = model[decl]
    except Z3Exception:
        fi = None
    if fi is None:
        return [], None
    if not isinstance(fi, FuncInterp):
        return [], fi
    out = []
    for i in range(fi.num_entries()):
        e = fi.entry(i)
        out.append(([e.arg_value(j) for j in range(e.num_args())],
                    e.value()))
    return out, fi.else_value()


def _harvest(expr, positions, tag):
    """Collect constants c from atoms  Var(i) == c  inside a symbolic
    interpretation and tag each with the local sort positions[i]."""
    if expr is None:
        return
    stack = [expr]
    while stack:
        e = stack.pop()
        if not is_app(e):
            continue
        if is_eq(e) and e.num_args() == 2:
            a, b = e.arg(0), e.arg(1)
            for x, y in ((a, b), (b, a)):
                if is_var(x) and _is_value(y):
                    i = get_var_index(x)
                    if i < len(positions):
                        tag(positions[i], y)
        for k in range(e.num_args()):
            stack.append(e.arg(k))


def _product_size(cands):
    n = 1
    for c in cands:
        n *= len(c)
        if n == 0 or n > MAX_TUPLES:
            return n
    return n


def _product(cands):
    idx = [0] * len(cands)
    while True:
        yield [cands[i][idx[i]] for i in range(len(cands))]
        j = len(cands) - 1
        while j >= 0:
            idx[j] += 1
            if idx[j] < len(cands[j]):
                break
            idx[j] = 0
            j -= 1
        if j < 0:
            return


class _Pool:
    """Values seen in the model, keyed by a tag (local or global sort);
    duplicate-free, deterministic order."""

    def __init__(self):
        self.d = {}

    def add(self, tag, v):
        if v is None:
            return
        lst = self.d.setdefault(tag, [])
        if not any(eq(v, x) for x in lst):
            lst.append(v)

    def get(self, tag):
        return sorted(self.d.get(tag, []), key=_key)


def _probe(model, decl, col, v, known):
    """A tuple of `decl` that is TRUE in `model` and has value `v` in column
    `col` (None: any column), other than the tuples in `known`; or None.
    The relation's interpretation, evaluated on fresh constants, is a
    quantifier-free formula, so this is a small, quick sub-solver query."""
    xs = [FreshConst(decl.domain(i), "t") for i in range(decl.arity())]
    # no model completion: the fresh constants must stay symbolic
    body = model.eval(decl(*xs), model_completion=False)
    if is_false(body):
        return None
    s = Solver()
    s.set("timeout", 2000)
    s.add(body)
    for x, d in zip(xs, column_domains.get(decl.name(), [])):
        if d is not None:                     # in-domain tuples only
            s.add(d(x))
    if col is not None:
        s.add(xs[col] == v)
    for r in known:
        s.add(Not(And([x == a for x, a in zip(xs, r)])))
    if s.check() != sat:
        return None
    m = s.model()
    return [m.eval(x, model_completion=True) for x in xs]


def localize_model(model, witnesses):
    """Map a model over Z3 built-in sorts back to LOCAL sorts.

    The local sort of every value is read off the position at which it
    occurs: column i of predicate p has local sort Arity[p][i]; argument i of
    function f has local sort args[i] and its result has sort ret.
    """
    # values of interest, pooled by GLOBAL sort: joins (equalities between
    # columns) are only meaningful between local sorts of one global sort
    by_local, by_global = _Pool(), _Pool()

    def seen(local, v):
        by_local.add(local, v)
        by_global.add(sort_of.get(local, local), v)

    assign = []
    for var, local, expr in list(witnesses) + list(free_vars):
        v = _ev(model, expr)
        assign.append((var, local, v))
        if v is not None:
            seen(local, v)

    literals = []
    for text, expr, label in literal_decls:
        v = _ev(model, expr)
        literals.append((text, label, v))
        if v is not None:
            seen(label, v)

    for name, decl, cols in predicate_decls:
        entries, default = _entries(model, decl)
        for args, val in entries:
            if is_true(val):
                for local, a in zip(cols, args):
                    seen(local, a)
        _harvest(default, cols, seen)
    for name, decl, args_s, ret in function_decls:
        entries, default = _entries(model, decl)
        for args, val in entries:
            for local, a in zip(args_s, args):
                seen(local, a)
            seen(ret, val)
        _harvest(default, args_s, seen)

    domains = _Pool()
    for _var, local, v in assign:
        domains.add(local, v)

    rows_of = {}
    symbolic_of = {}
    for name, decl, cols in predicate_decls:
        entries, default = _entries(model, decl)
        doms = column_domains.get(name, [])
        rows_of[name] = [a for a, val in entries if is_true(val) and all(
            d is None or is_true(_ev(model, d(x))) for x, d in zip(a, doms))]
        symbolic_of[name] = default is not None and not is_false(default)

    # tuples made of the witnesses' / answer variables' / literals' values
    # (in particular the witness tuples themselves) are listed first
    for name, decl, cols in predicate_decls:
        cands = [by_local.get(c) for c in cols]
        if not symbolic_of[name] or _product_size(cands) > MAX_TUPLES:
            continue
        doms = column_domains.get(name, [])
        for args in _product(cands):
            if is_true(_ev(model, decl(*args))) and all(
                    d is None or is_true(_ev(model, d(x)))
                    for x, d in zip(args, doms)) and not any(
                    all(eq(a, b) for a, b in zip(args, r))
                    for r in rows_of[name]):
                rows_of[name].append(args)
        for r in rows_of[name]:
            for local, a in zip(cols, r):
                seen(local, a)

    # Join closure: for every value of interest and every predicate column of
    # the same GLOBAL sort, find a tuple holding that value there (if any);
    # the new tuples' values are of interest in turn.  This lists exactly the
    # tuples needed to follow joins / foreign keys through the model.
    probed, probes, complete = set(), 0, True
    changed = True
    while changed:
        changed = False
        for name, decl, cols in predicate_decls:
            if not symbolic_of[name]:
                continue
            rows = rows_of[name]
            targets = [(None, None)]
            for i, c in enumerate(cols):
                for v in by_global.get(sort_of.get(c, c)):
                    targets.append((i, v))
            for i, v in targets:
                key = (name, i, None if v is None else
                       (str(v.sort()), str(v)))
                if key in probed:
                    continue
                if i is not None and any(eq(r[i], v) for r in rows):
                    probed.add(key)
                    continue
                if probes >= MAX_PROBES:
                    complete = False
                    break
                probed.add(key)
                probes += 1
                t = _probe(model, decl, i, v, rows)
                if t is not None:
                    rows.append(t)
                    changed = True
                    for local, a in zip(cols, t):
                        seen(local, a)

    relations = []
    for name, decl, cols in predicate_decls:
        rows = sorted(rows_of[name], key=lambda r: [_key(a) for a in r])
        for r in rows:
            for local, a in zip(cols, r):
                domains.add(local, a)
        relations.append((name, cols, rows, complete, symbolic_of[name]))

    functions = []
    for name, decl, args_s, ret in function_decls:
        cands = [by_local.get(a) or by_global.get(sort_of.get(a, a))
                 for a in args_s]
        rows = []
        if _product_size(cands) <= MAX_TUPLES:
            for args in _product(cands):
                rows.append((args, _ev(model, decl(*args))))
        for args, val in rows:
            for local, a in zip(args_s, args):
                domains.add(local, a)
            domains.add(ret, val)
        functions.append((name, args_s, ret, rows))

    return {"assign": assign, "literals": literals, "relations": relations,
            "functions": functions, "probes": probes,
            "domains": dict((k, domains.get(k)) for k in sorted(domains.d))}


def print_model(model, witnesses, witness_label):
    """Print a counter-model in terms of LOCAL sorts; return its summary."""
    lm = localize_model(model, witnesses)
    print("  --- counter-model (local sorts) ---")

    nw = len(witnesses)
    if nw:
        print("  %s witnesses:" % witness_label)
        for var, local, v in lm["assign"][:nw]:
            print("    %s : %s = %s" % (var, local, _show(v, local)))
    if lm["assign"][nw:]:
        print("  free (answer) variables:")
        for var, local, v in lm["assign"][nw:]:
            print("    %s : %s = %s" % (var, local, _show(v, local)))
    if lm["literals"]:
        print("  literals / constants:")
        for text, label, v in lm["literals"]:
            print("    %s : %s = %s" % (text, label, _show(v, label)))

    print("  relations (each value tagged with the local sort of its "
          "position):")
    for name, cols, rows, complete, symbolic in lm["relations"]:
        print("    %s(%s):" % (name, ", ".join(cols)))
        if not rows:
            print("      <empty over the values of this model>")
        for r in rows:
            print("      %s(%s)" % (name, ", ".join(
                "%s=%s" % (c, _show(a, c)) for c, a in zip(cols, r))))
        if not complete:
            print("      [probe limit reached; listing may be incomplete]")
        if symbolic:
            print("      [Z3 gave this relation symbolically; listed: one "
                  "tuple per value of interest per column (join closure)]")

    for name, args_s, ret, rows in lm["functions"]:
        print("    function %s(%s) -> %s:" % (name, ", ".join(args_s), ret))
        for args, v in rows:
            print("      %s(%s) = %s:%s" % (name, ", ".join(
                "%s=%s" % (c, _show(a, c)) for c, a in zip(args_s, args)),
                ret, _show(v, ret)))

    print("  local-sort domains (values occurring at positions of each "
          "local sort):")
    width = max([len(k) for k in lm["domains"]] or [0])
    for local, vals in lm["domains"].items():
        print("    %s : {%s}" % (local.ljust(width),
                                 ", ".join(_show(v, local) for v in vals)))

    shared = {}
    for local, vals in lm["domains"].items():
        for v in vals:
            key = (sort_of.get(local, local), str(v))
            shared.setdefault(key, (v, []))[1].append(local)
    joins = [(v, ls) for _k, (v, ls) in sorted(shared.items())
             if len(ls) > 1]
    if joins:
        print("  values shared across local sorts (joins):")
        for v, ls in joins:
            print("    %s : %s" % (_show(v), ", ".join(ls)))
    return lm


# Strings + quantifiers make Z3's search heavy-tailed: a single run may stall
# where a run with another random seed answers in milliseconds.  Restarts
# follow a fixed (seed, timeout) schedule, so the procedure is deterministic.
RESTART_SCHEDULE = [(seed, ms) for ms in (2000, 8000, 30000, 120000)
                    for seed in (0, 1, 2, 3)]


def _check(sid, name, claim, witnesses, witness_label):
    """unsat means the direction holds; sat yields a counter-model."""
    _LOG.stage(sid)
    _LOG.info("solver: %d background assertion(s) + claim; witnesses %s"
              % (len(background),
                 ", ".join(str(w) for _v, _l, w in witnesses) or "-"))
    if _LOG.wants(2):
        _LOG.detail("claim: %s" % " ".join(str(claim).split()))
    r, s, attempts = unknown, None, 0
    for seed, ms in RESTART_SCHEDULE:
        attempts += 1
        s = Solver()
        s.set("random_seed", seed)
        s.set("timeout", ms)
        for f in background:
            s.add(f)
        s.add(claim)
        t0 = _time.perf_counter()
        r = s.check()
        _LOG.detail("attempt %d: seed=%d timeout=%dms -> %s%s%s"
                    % (attempts, seed, ms, r,
                       " (%s)" % s.reason_unknown() if r == unknown else "",
                       " in %.3f s" % (_time.perf_counter() - t0)
                       if _LOG.timings else ""))
        if r != unknown:
            break
    meaning = ("  -> direction FAILS (counter-model)" if r == sat else
               "  -> direction holds" if r == unsat else "")
    _LOG.info("result: %s after %d attempt(s)%s" % (r, attempts, meaning))
    print("[%s] %s" % (name, r))
    if r == sat:
        import contextlib
        import io
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            lm = print_model(s.model(), witnesses, witness_label)
        text = buf.getvalue()
        _sys.stdout.write(text)
        _LOG.info("counter-model: %d relation tuple(s) listed, %d probe "
                  "quer%s" % (sum(len(rel[2]) for rel in lm["relations"]),
                               lm["probes"],
                               "y" if lm["probes"] == 1 else "ies"))
        for ln in text.splitlines():
            _LOG.detail(ln)
    elif r == unknown:
        print("  reason: %s" % s.reason_unknown())
    return r


def main(argv=None):
    _LOG.configure(_sys.argv[1:] if argv is None else argv)
    _LOG.heading("==== checking ====")
    try:
        return _main()
    except Exception as exc:
        _LOG.fail(exc)
        raise
    finally:
        _LOG.close()


def _main():
    _LOG.stage("R1")
    _LOG.info("%d assertion(s): %d sort axiom(s), %d free-variable "
              "domain(s), %d order axiom(s), %d FOL axiom(s), %d uniqueness"
              % (len(background), len(sort_axioms), len(free_var_domains),
                 len(order_axioms), len(axioms), len(uniqueness)))
    if _LOG.wants(2):
        for i, f in enumerate(background):
            _LOG.detail("[%d] %s" % (i, " ".join(str(f).split())))
    if undefined_orders:
        _LOG.info("WARNING: no order defined on %s"
                  % ", ".join(undefined_orders))
    if undefined_orders:
        print("WARNING: comparison on sort(s) %s, which have no built-in "
              "order in Z3." % ", ".join(undefined_orders))
        print("         They use uninterpreted relations LT_<sort> that NEED "
              "A DEFINITION (see order_axioms).")
        print()
    # Skolemising the leading existential prefix of the asserted side is
    # satisfiability-preserving and makes the witnesses readable in the model.
    r1 = _check("R2", "gold |= predicted ?",
                And(gold_skolem, Not(predicted)),
                gold_witnesses, "Gold")
    r2 = _check("R3", "predicted |= gold ?",
                And(predicted_skolem, Not(gold)),
                predicted_witnesses, "Predicted")
    _LOG.stage("R4")
    print()
    if r1 == unsat and r2 == unsat:
        verdict = "EQUIVALENT"
    elif r1 == sat or r2 == sat:
        verdict = "NOT EQUIVALENT"
    else:
        verdict = "UNKNOWN"
    if undefined_orders and verdict == "NOT EQUIVALENT" and not order_axioms:
        verdict += (" (possibly only because the order on %s is undefined)"
                    % ", ".join(undefined_orders))
    print("VERDICT:", verdict)
    _LOG.info("VERDICT: %s" % verdict)
    _LOG.done()
    return verdict


if __name__ == "__main__":
    main()
